// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bool ok;
        vm.prank(caller);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        bool callerIsOwner = caller == address(uint160(uint256(keccak256(abi.encodePacked(bytes32(uint256(uint160(address(c)))))))));
        address owner = address(this);
        bool expectedOk = (caller == owner);
        assertTrue(ok == expectedOk);
    }
}
